// Radio-Reihenfolge: 1 Nachrichten, 2 Wetter, 3 Tageslaenge, 4 anderes (dieser Flow baut das Wetter).

const SRC = 'https://www.wien.gv.at/svc/weather/today-and-daytime';
const HIGHBELL = 'http://192.168.0.50/audio/tts/highbell24.mp3';
const OUT = '/share/htdocs/audio/tts/wetter.mp3';
const UA = 'Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36';
const MAX = 200;

function fetchBuf(url, depth) {
    depth = depth == null ? 3 : depth;
    return new Promise((resolve, reject) => {
        const lib = url.indexOf('https:') === 0 ? https : http;
        const r = lib.get(url, { headers: { 'User-Agent': UA, 'Accept': '*/*' }, timeout: 30000 }, res => {
            if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location && depth > 0) {
                const loc = res.headers.location;
                res.resume();
                let next;
                if (/^https?:\/\//i.test(loc)) next = loc;
                else if (loc.charAt(0) === '/') next = url.match(/^(https?:\/\/[^\/]+)/)[1] + loc;
                else next = url.replace(/\/[^\/]*$/, '/') + loc;
                resolve(fetchBuf(next, depth - 1));
                return;
            }
            const chunks = [];
            res.on('data', c => chunks.push(c));
            res.on('end', () => resolve({ status: res.statusCode, body: Buffer.concat(chunks) }));
        });
        r.on('timeout', () => r.destroy(new Error('timeout ' + url)));
        r.on('error', reject);
    });
}

function decodeEntities(s) {
    const named = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', auml: 'ä', ouml: 'ö', uuml: 'ü', Auml: 'Ä', Ouml: 'Ö', Uuml: 'Ü', szlig: 'ß', ndash: '–', mdash: '—', hellip: '…', deg: '°' };
    return s
        .replace(/&#x([0-9a-fA-F]+);/g, (_, h) => String.fromCharCode(parseInt(h, 16)))
        .replace(/&#(\d+);/g, (_, d) => String.fromCharCode(parseInt(d, 10)))
        .replace(/&([a-zA-Z]+);/g, (m, n) => (named[n] != null ? named[n] : m));
}

function extractWeather(html) {
    const re = /<p[^>]*class="[^"]*wm-weather-intraday__temp[^"]*"[^>]*>([\s\S]*?)<\/p>/gi;
    let m;
    while ((m = re.exec(html)) !== null) {
        let txt = m[1].replace(/<[^>]+>/g, ' ');
        txt = decodeEntities(txt).replace(/\s+/g, ' ').trim();
        if (txt.length > 20) return txt;
    }
    return '';
}

function hardSplit(s) {
    const out = [];
    let rest = s;
    while (rest.length > MAX) {
        let cut = rest.lastIndexOf(' ', MAX);
        if (cut < 40) cut = MAX;
        out.push(rest.slice(0, cut).trim());
        rest = rest.slice(cut).trim();
    }
    if (rest) out.push(rest);
    return out;
}

function split200(text) {
    const sents = text.replace(/\s+/g, ' ').trim().split(/(?<=[.!?])\s+/);
    const out = [];
    let cur = '';
    for (let i = 0; i < sents.length; i++) {
        const s = sents[i];
        if (!s) continue;
        const cand = cur ? cur + ' ' + s : s;
        if (cand.length <= MAX) {
            cur = cand;
        } else {
            if (cur) out.push(cur);
            if (s.length > MAX) {
                const hs = hardSplit(s);
                for (let j = 0; j < hs.length; j++) out.push(hs[j]);
                cur = '';
            } else {
                cur = s;
            }
        }
    }
    if (cur) out.push(cur);
    return out;
}

(async () => {
    const page = await fetchBuf(SRC);
    if (page.status !== 200) throw new Error('wien.gv.at HTTP ' + page.status);
    const text = extractWeather(page.body.toString('utf8'));
    if (!text) throw new Error('kein wm-weather-intraday__temp mit Text gefunden');

    const chunks = split200(text);
    node.warn('Wettertext ' + text.length + ' Zeichen -> ' + chunks.length + ' Chunk(s): ' + chunks.map(c => c.length).join('/'));

    const hb = await fetchBuf(HIGHBELL);
    if (hb.status !== 200 || hb.body.length === 0) throw new Error('highbell HTTP ' + hb.status);

    const parts = [];
    for (let i = 0; i < chunks.length; i++) {
        const q = encodeURIComponent(chunks[i]);
        const t = await fetchBuf('https://translate.google.com/translate_tts?ie=UTF-8&client=tw-ob&tl=de-DE&ttsspeed=1&q=' + q);
        if (t.status !== 200 || t.body.length === 0) throw new Error('TTS HTTP ' + t.status + ' bei Chunk ' + (i + 1));
        parts.push(t.body);
    }
    parts.push(hb.body); // highbell nur am Ende = Trenner zum naechsten Segment

    const audio = Buffer.concat(parts);
    fs.mkdirSync(OUT.replace(/\/[^\/]+$/, ''), { recursive: true });
    fs.writeFileSync(OUT, audio);

    node.status({ fill: 'green', shape: 'dot', text: audio.length + ' B, ' + chunks.length + ' Chunk(s)' });
    msg.payload = { ok: true, file: OUT, bytes: audio.length, chunks: chunks.length, chunk_texts: chunks, text: text };
    node.send(msg);
})().catch(err => {
    node.status({ fill: 'red', shape: 'ring', text: 'Fehler' });
    node.error(err, msg);
    msg.payload = { ok: false, error: err.message };
    node.send(msg);
});
return null;

if (msg.start && msg.end) {
