  const ver=(b1>>3)&3, layer=(b1>>1)&3;
  const brIdx=(b2>>4)&15, srIdx=(b2>>2)&3, pad=(b2>>1)&1;
  if(ver===1||layer!==1||brIdx===0||brIdx===15||srIdx===3){i++;continue;}
  const mpeg1=ver===3;
  const br=(mpeg1?brM1:brM2)[brIdx]*1000;
  const sr=(mpeg1?srM1:(ver===2?srM2:srM25))[srIdx];
  const samples=mpeg1?1152:576;
  const len=Math.floor((samples/8)*br/sr)+pad;
  if(len<=0||i+len>buf.length){i++;continue;}
  dur+=samples/sr;frames++;i+=len;
}
msg.finalSeconds = +dur.toFixed(3);
msg.finalBytes = buf.length;
msg.finalFrames = frames;
const stopDelay = Math.round(dur*1000)+3000;
const fadeDelay = Math.round(dur*1000);
node.warn('Final '+msg.finalSeconds+' s, stopDelay '+stopDelay+' ms, fadeDelay '+fadeDelay+' ms');
const stopMsg = Object.assign({}, msg, { delay: stopDelay });
const fadeMsg = Object.assign({}, msg, { delay: fadeDelay });
return [stopMsg, fadeMsg];

const d = Number(msg.delay) || 5000;
node.warn('Warte '+d+' ms');
setTimeout(() => { node.send(msg); }, d);

const url = 'http://192.168.0.25/httpapi.asp?command=getPlayerStatus';
http.get(url, res => {
  let b=''; res.on('data', c => b += c);
  res.on('end', () => {
    try {
      const d = JSON.parse(b);
      const t = Number(d.totlen) || 0;
      msg.totlen = t;
      node.warn('Status totlen='+t+' status='+d.status);
      if (t > 0 && t < 250000) {
        msg.url = 'http://192.168.0.25/httpapi.asp?command=setPlayerCmd:stop';
        msg.payload = msg.url;
        node.send(msg);
      } else {
        node.warn('Kein Stop (Kontrollpunkt oder idle), totlen='+t);
      }
    } catch (e) { node.error('Status parse: '+e.message); }
  });
}).on('error', e => node.error('Status: '+e.message));

const d = Number(msg.delay) || 5000;
node.warn('Wait final end ' + d + ' ms');
setTimeout(() => {
  node.send({});
}, d);
